from collections import deque
def transform(g):
    H,W=len(g),len(g[0])
    fr=[r for r in range(H) if all(x==2 for x in g[r])][0]
    step = -1 if fr==H-1 else 1  # falling direction
    out=[[0]*W for _ in range(H)]
    out[fr]=[2]*W
    seen=[[False]*W for _ in range(H)]
    comps=[]
    for r in range(H):
        for c in range(W):
            v=g[r][c]
            if v in (0,2) or seen[r][c]: continue
            cells=[]; q=deque([(r,c)]); seen[r][c]=True
            while q:
                a,b=q.popleft(); cells.append((a,b))
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<H and 0<=nb<W and not seen[na][nb] and g[na][nb]==v:
                        seen[na][nb]=True; q.append((na,nb))
            comps.append(cells)
    moved=True
    while moved:
        moved=False
        for cells in comps:
            try:
                if all(0<=r+step<H and out[r+step][c]==0 for r,c in cells):
                    for r,c in cells: out[r][c]=0
                    for r,c in cells: out[r+step][c]=g[r][c]
                    moved=True
            except IndexError:
                pass
    return out

